"    const targetPrinters = kotPrinterConfig.names && kotPrinterConfig.names.length > 0
      ? kotPrinterConfig.names
      : [kotPrinterConfig.name || posSettings.printerName || 'Default'];

    if (window.require) {
      try {
        const { ipcRenderer } = window.require('electron');
        targetPrinters.forEach(pName => {
          ipcRenderer.send('print-silent', {
            html: receiptHtml.replace('<script>window.onload = () => { window.print(); window.close(); }</script>', ''),
            printerName: pName
          });
        });
        return;
      } catch (err) {
        console.error("Silent KOT print failed:", err);
      }
    }

    const printWindow = window.open('', '_blank', 'width=300,height=600');
    if (!printWindow) {
      toast.error("Failed to open print window. Please allow popups.");
      return;
    }
    printWindow.document.write(receiptHtml);
    printWindow.document.close();"

